-- ============================================================
-- 个人管理系统 数据库设计 (H2 内存数据库兼容版)
-- 说明：与 MySQL 版本的差异——
--   1. 去掉了 CREATE DATABASE / USE（数据库由连接串 jdbc:h2:mem:person_admin 指定）
--   2. AUTO_INCREMENT 改为 GENERATED BY DEFAULT AS IDENTITY
--   3. 去掉了 ENGINE / CHARSET / COMMENT / KEY 索引子句 / ON UPDATE CURRENT_TIMESTAMP
--   4. 去掉了针对旧库的 ALTER 升级脚本（全新库无需执行）
--   5. 列名 value 是 H2 保留字，分别改名为 market_value / current_value / asset_value
-- 如需切回 MySQL，请使用 MySQL 8.x 原版脚本并修改 application.yml 的数据源配置
-- ============================================================

CREATE TABLE IF NOT EXISTS person (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(50)  NOT NULL,
    age   INT,
    email VARCHAR(100)
);

-- ------------------------------------------------------------
-- 0. 用户表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sys_user (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username    VARCHAR(32)  NOT NULL UNIQUE,
    password    VARCHAR(128) NOT NULL,             -- BCrypt加密后的密码
    nickname    VARCHAR(32)  NOT NULL DEFAULT '',
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ------------------------------------------------------------
-- 1. 收入记录
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS income (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT        NOT NULL,            -- 所属用户
    amount      DECIMAL(12,2) NOT NULL,            -- 金额(元)
    category    VARCHAR(32)   NOT NULL,            -- 分类：工资/奖金/兼职/理财收益/红包/其他
    record_date DATE          NOT NULL,            -- 收入日期
    asset_id    BIGINT        DEFAULT NULL,        -- 入账资产（仅现金/银行卡类别）
    remark      VARCHAR(255)  NOT NULL DEFAULT '', -- 备注
    create_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_income_user_date ON income (user_id, record_date);
CREATE INDEX IF NOT EXISTS idx_income_category  ON income (category);

-- ------------------------------------------------------------
-- 2. 支出记录
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS expense (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT        NOT NULL,
    amount      DECIMAL(12,2) NOT NULL,
    category    VARCHAR(32)   NOT NULL,            -- 分类：餐饮/交通/住房/购物/娱乐/医疗/教育/其他
    record_date DATE          NOT NULL,
    asset_id    BIGINT        DEFAULT NULL,        -- 支付资产（仅现金/银行卡类别）
    investment_id BIGINT      DEFAULT NULL,        -- 分类为「投资」时关联的投资标的（资产减少联动投资增加）
    remark      VARCHAR(255)  NOT NULL DEFAULT '',
    create_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_expense_user_date ON expense (user_id, record_date);
CREATE INDEX IF NOT EXISTS idx_expense_category  ON expense (category);

-- ------------------------------------------------------------
-- 3. 投资标的
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS investment (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT        NOT NULL,
    name            VARCHAR(64)   NOT NULL,          -- 标的名称，如：沪深300ETF
    type            VARCHAR(16)   NOT NULL,          -- 类型：股票/基金/债券/理财/黄金/其他
    code            VARCHAR(20)   DEFAULT NULL,      -- 行情代码（选填）：股票带市场前缀 sh600519/sz000001，基金为 6 位数字
    amount          DECIMAL(14,2) NOT NULL,          -- 累计投入金额(元)
    current_value   DECIMAL(14,2) NOT NULL,          -- 当前市值(元)
    shares          INT           DEFAULT NULL,      -- 持股数量(仅股票类)
    source_asset_id BIGINT        DEFAULT NULL,      -- 出资资产（仅现金/银行卡类别，买卖联动该资产余额）
    source_channel  VARCHAR(16)   DEFAULT NULL,      -- 外部渠道来源：THS=同花顺同步（非空则投资由渠道维护，不支持编辑/卖出/删除）
    fee_rate        DECIMAL(8,6)  NOT NULL DEFAULT 0,-- 交易费率（%）：比例费用（佣金/征费等），买入 ×(1+费率)、卖出 ×(1-费率)
    fee_fixed       DECIMAL(12,2) NOT NULL DEFAULT 0,-- 每笔固定手续费(元，人民币)：印花税取整/最低佣金/尾差等比例拟合不了的费用
    buy_date        DATE          NOT NULL,
    remark          VARCHAR(255)  NOT NULL DEFAULT '',
    create_time     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_investment_user      ON investment (user_id);
CREATE INDEX IF NOT EXISTS idx_investment_buy_date  ON investment (buy_date);
CREATE INDEX IF NOT EXISTS idx_investment_type      ON investment (type);
CREATE INDEX IF NOT EXISTS idx_investment_code      ON investment (code);

-- ------------------------------------------------------------
-- 4. 投资每日市值快照
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS investment_value_history (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT        NOT NULL,
    investment_id BIGINT        NOT NULL,
    value_date    DATE          NOT NULL,
    market_value  DECIMAL(14,2) NOT NULL,          -- 当日市值(元)
    price         DECIMAL(12,4) DEFAULT NULL,      -- 每股价格(仅股票类)
    create_time   DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_inv_date UNIQUE (investment_id, value_date)
);
CREATE INDEX IF NOT EXISTS idx_inv_val_user_date ON investment_value_history (user_id, value_date);

-- ------------------------------------------------------------
-- 4.1 投资买卖交易记录（K 线买卖标记与历史盈亏计算的数据源）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS investment_trade (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT        NOT NULL,
    investment_id   BIGINT        NOT NULL,
    trade_type      VARCHAR(8)    NOT NULL,          -- BUY=买入 / SELL=卖出
    trade_date      DATE          NOT NULL,          -- 交易发生日期
    shares          INT           DEFAULT NULL,      -- 股数/份额（金额型投资为 NULL）
    price           DECIMAL(14,4) DEFAULT NULL,      -- 成交单价（股票为对应币种股价/净值，人民币标的即人民币）
    amount          DECIMAL(14,2) NOT NULL,          -- 成交金额（人民币，买入=投入，卖出=回款）
    fee             DECIMAL(14,2) DEFAULT NULL,      -- 本笔手续费（人民币，买入=额外付出，卖出=从回款扣除；无费用为 0）
    target_asset_id BIGINT        DEFAULT NULL,      -- 卖出资金去向资产（仅 SELL）
    remark          VARCHAR(255)  NOT NULL DEFAULT '',
    create_time     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_inv_trade_invest ON investment_trade (investment_id, trade_date);
CREATE INDEX IF NOT EXISTS idx_inv_trade_user   ON investment_trade (user_id);

-- ------------------------------------------------------------
-- 5. 资产
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS asset (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT        NOT NULL,
    name          VARCHAR(64)   NOT NULL,          -- 资产名称，如：招商银行储蓄卡
    category      VARCHAR(16)   NOT NULL,          -- 类别：现金/银行卡/房产/车辆/电子产品/其他
    current_value DECIMAL(14,2) NOT NULL,          -- 当前估值(元)
    change_date   DATE,                            -- 入账/变更日期（用户指定，折线图从该日起计值，空=今日）
    remark        VARCHAR(255)  NOT NULL DEFAULT '',
    create_time   DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time   DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_asset_user     ON asset (user_id);
CREATE INDEX IF NOT EXISTS idx_asset_category ON asset (category);

-- ------------------------------------------------------------
-- 6. 资产估值历史
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS asset_value_history (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT        NOT NULL,
    asset_id    BIGINT        NOT NULL,
    value_date  DATE          NOT NULL,
    asset_value DECIMAL(14,2) NOT NULL,            -- 当日估值(元)
    create_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_asset_date UNIQUE (asset_id, value_date)
);
CREATE INDEX IF NOT EXISTS idx_asset_val_user_date ON asset_value_history (user_id, value_date);

-- ------------------------------------------------------------
-- 7. 体重记录
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS body_weight (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    record_date DATE         NOT NULL,
    weight      DECIMAL(5,2) NOT NULL,             -- 体重(kg)
    note        VARCHAR(255) NOT NULL DEFAULT '',
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_weight_user_date UNIQUE (user_id, record_date)
);

-- ------------------------------------------------------------
-- 8. 饮食记录
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS diet_record (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    record_date DATE         NOT NULL,
    meal_type   VARCHAR(8)   NOT NULL,             -- 餐次：早餐/午餐/晚餐/加餐
    food        VARCHAR(128) NOT NULL,
    calories    INT          NOT NULL DEFAULT 0,   -- 热量(千卡)
    remark      VARCHAR(255) NOT NULL DEFAULT '',
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_diet_user_date ON diet_record (user_id, record_date);
CREATE INDEX IF NOT EXISTS idx_diet_meal      ON diet_record (meal_type);

-- ------------------------------------------------------------
-- 9. 每日资产/投资市值快照（任何变动自动记录，删除时记 0）
--    折线图据此展示历史变化：某资产/投资清零时曲线落到 0 而不是消失
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS daily_snapshot (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT        NOT NULL,
    snapshot_date DATE          NOT NULL,            -- 日期（天维度）
    kind          VARCHAR(16)   NOT NULL,            -- ASSET 资产 / INVEST 投资
    ref_id        BIGINT        NOT NULL,            -- 关联 asset.id 或 investment.id
    name          VARCHAR(64),                       -- 冗余名称，删除后仍可读
    type          VARCHAR(32),                       -- 资产类别 / 投资类型
    total_value   DECIMAL(14,2) NOT NULL,            -- 当日市值/估值
    invest_amount DECIMAL(14,2) DEFAULT NULL,        -- 当日累计投入（仅投资行；历史盈亏 = total_value - invest_amount）
    price         DECIMAL(12,4) DEFAULT NULL,        -- 每股价格（仅股票类投资）
    CONSTRAINT uk_snapshot UNIQUE (user_id, snapshot_date, kind, ref_id)
);
CREATE INDEX IF NOT EXISTS idx_snapshot_user ON daily_snapshot (user_id, snapshot_date);

-- ------------------------------------------------------------
-- 10. 每日行情落库（交易日收盘后由 DailyMarketValueRecordTask 写入）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS market_quote (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(20)   NOT NULL,            -- 行情代码：sh600519 / 110022
    name        VARCHAR(100),                      -- 标的名称（冗余，便于直接阅读）
    type        VARCHAR(10)   NOT NULL,            -- STOCK 股票 / FUND 基金
    trade_date  DATE          NOT NULL,            -- 交易日
    price       DECIMAL(18,4) NOT NULL,            -- 当日收盘价 / 基金估算净值
    create_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_market_quote UNIQUE (code, trade_date)
);
CREATE INDEX IF NOT EXISTS idx_market_quote_code ON market_quote (code, trade_date);

-- ------------------------------------------------------------
-- 11. 汇率历史（每日每币种一条；当日最新值走缓存，历史落本表）
--     rate 含义：1 单位外币 = rate 人民币
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS exchange_rate (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    currency    VARCHAR(8)    NOT NULL,            -- USD/JPY/HKD/EUR/GBP
    rate        DECIMAL(18,6) NOT NULL,            -- 1 单位外币兑换的人民币
    rate_date   DATE          NOT NULL,            -- 日期
    create_time DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_exchange_rate UNIQUE (currency, rate_date)
);
CREATE INDEX IF NOT EXISTS idx_exchange_rate_currency ON exchange_rate (currency, rate_date);

-- ------------------------------------------------------------
-- 12. 外部渠道账户（用户手动添加并校验账户名后，才允许该渠道推送同步数据）
--     channel 预留多数据源扩展：THS=同花顺，后续可加 XQ(雪球)/BROKER 等
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS external_channel (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT       NOT NULL,
    channel        VARCHAR(32)  NOT NULL,            -- 渠道标识：THS 等
    account_name   VARCHAR(64)  NOT NULL,            -- 渠道账户名（同花顺登录用户名），同步时校验匹配
    status         VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',  -- ACTIVE / SYNC_ERROR / DISABLED
    api_key        VARCHAR(64)  NOT NULL,            -- 推送凭证（添加渠道时生成，仅用户本人可见，X-Api-Key 头校验）
    last_sync_time DATETIME     DEFAULT NULL,        -- 上次同步时间
    last_sync_msg  VARCHAR(255) NOT NULL DEFAULT '', -- 上次同步结果（新增/更新/跳过/未匹配数）
    remark         VARCHAR(255) NOT NULL DEFAULT '',
    create_time    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_external_channel UNIQUE (user_id, channel, account_name)
);
CREATE INDEX IF NOT EXISTS idx_external_channel_user ON external_channel (user_id);
CREATE INDEX IF NOT EXISTS idx_external_channel_key ON external_channel (api_key);
